type Size = 'sm' | 'md' | 'lg';

const chosen: Size = 'md'; // stays the literal type 'md'

function setSize(size: Size): string { return size; }

console.log(setSize(chosen));

const LEVELS = ['debug', 'info', 'warn', 'error'] as const;
type Level = typeof LEVELS[number]; // 'debug' | 'info' | 'warn' | 'error'

function log(level: Level, message: string): string {
  return '[' + level.toUpperCase() + '] ' + message;
}

console.log(log('info', 'started'));
console.log(log('error', 'boom'));
